"use client"
import React, { useState } from "react"
import useOrderStore from "@/store/orderStore"
import Image from "next/image"
import { Grid, List, Calendar, Package2, RefreshCw, Search, Filter } from "lucide-react"

export default function CancellationsPage() {
  const { cancellations } = useOrderStore()


  re (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gradient-to-r from-gray-50 to-gray-100">
            <tr>
              <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                Product
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider hidden sm:table-cell">
                Order ID
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider hidden md:table-cell">
                Cancelled Date
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider hidden lg:table-cell">
                Amount
              </th>
              <th className="px-6 py-4 text-center text-xs font-semibold text-gray-600 uppercase tracking-wider">
                Status
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {filteredCancellations.map((order, index) => (
              <tr 
                key={order.id} 
                className={`hover:bg-red-50 transition-colors duration-150 ${
                  index % 2 === 0 ? 'bg-white' : 'bg-gray-50'
                }`}
              >
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center space-x-4">
                    <div className="flex-shrink-0 relative">
                      <div className="h-14 w-14 rounded-lg overflow-hidden bg-gray-100 border-2 border-gray-200">
                        <Image
                          src={order.image || "/placeholder.png"}
                          alt={order.name}
                          width={56}
                          height={56}
                          className="h-full w-full object-cover"
                        />
                      </div>
                      <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center">
                        <span className="text-white text-xs">✕</span>
                      </div>
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-medium text-gray-900 truncate">
                        {order.name}
                      </p>
                      <p className="text-sm text-gray-500 sm:hidden">
                        #{order.id}
                      </p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap hidden sm:table-cell">
                  <div className="text-sm font-mono text-gray-900">#{order.id}</div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap hidden md:table-cell">
                  <div className="text-sm text-gray-900">
                    {order.cancelledDate || order.createdAt || order.date}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap hidden lg:table-cell">
                  <div className="text-sm font-medium text-gray-900">
                    {order.amount ? `Rs ${order.amount.toLocaleString()}` : 'N/A'}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-center">
                  <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800 border border-red-200">
                    <RefreshCw size={12} className="mr-1" />
                    {order.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )

  const CardView = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
      {filteredCancellations.map((order) => (
        <div
          key={order.id}
          className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden hover:shadow-md transition-all duration-200 hover:border-red-200"
        >
          <div className="relative">
            <div className="aspect-square bg-gray-100">
              <Image
                src={order.image || "/placeholder.png"}
                alt={order.name}
                width={300}
                height={300}
                className="w-full h-full object-cover"
              />
            </div>
            <div className="absolute top-3 right-3">
              <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-500 text-white shadow-sm">
                <RefreshCw size={10} className="mr-1" />
                Cancelled
              </span>
            </div>
          </div>
          
          <div className="p-4">
            <h3 className="font-medium text-gray-900 text-sm mb-2 line-clamp-2">
              {order.name}
            </h3>
            
            <div className="space-y-2 text-xs text-gray-500">
              <div className="flex justify-between">
                <span>Order ID:</span>
                <span className="font-mono">#{order.id}</span>
              </div>
              
              {order.amount && (
                <div className="flex justify-between">
                  <span>Amount:</span>
                  <span className="font-medium text-gray-900">
                    Rs {order.amount.toLocaleString()}
                  </span>
                </div>
              )}
              
              <div className="flex justify-between">
                <span>Date:</span>
                <span>{order.cancelledDate || order.createdAt || order.date}</span>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  )

  const EmptyState = () => (
    <div className="text-center py-16">
      <div className="mx-auto h-24 w-24 text-gray-300 mb-6">
        <Package2 size={96} className="mx-auto" />
      </div>
      <h3 className="text-lg font-medium text-gray-900 mb-2">No cancelled orders</h3>
      <p className="text-gray-500 max-w-md mx-auto">
        You haven't cancelled any orders yet. When you cancel an order, it will appear here for your reference.
      </p>
    </div>
  )

  const NoResultsState = () => (
    <div className="text-center py-16">
      <Search size={48} className="mx-auto text-gray-300 mb-4" />
      <h3 className="text-lg font-medium text-gray-900 mb-2">No results found</h3>
      <p className="text-gray-500">
        Try adjusting your search term or filters to find what you're looking for.
      </p>
    </div>
  )

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
            <div className="mb-4 sm:mb-0">
              <h1 className="text-2xl sm:text-3xl font-bold text-gray-900 flex items-center">
                <RefreshCw className="mr-3 text-red-500" size={28} />
                Cancelled Orders
              </h1>
              <p className="mt-2 text-gray-600">
                {cancellations.length} {cancellations.length === 1 ? 'order' : 'orders'} cancelled
              </p>
            </div>
            
            {/* View Mode Toggle */}
            <div className="flex items-center space-x-2 bg-white rounded-lg p-1 shadow-sm border">
              <button
                onClick={() => setViewMode('table')}
                className={`p-2 rounded-md transition-colors ${
                  viewMode === 'table' 
                    ? 'bg-red-500 text-white shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700 hover:bg-gray-100'
                }`}
              >
                <List size={18} />
              </button>
              <button
                onClick={() => setViewMode('cards')}
                className={`p-2 rounded-md transition-colors ${
                  viewMode === 'cards' 
                    ? 'bg-red-500 text-white shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700 hover:bg-gray-100'
                }`}
              >
                <Grid size={18} />
              </button>
            </div>
          </div>
        </div>

        {/* Filters and Search */}
        {cancellations.length > 0 && (
          <div className="mb-6 flex flex-col sm:flex-row gap-4">
            {/* Search */}
            <div className="relative flex-1">
              <Search size={18} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                placeholder="Search by product name or order ID..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent bg-white"
              />
            </div>
            
            {/* Sort */}
            <div className="relative">
              <Filter size={18} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="pl-10 pr-8 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent bg-white appearance-none cursor-pointer"
              >
                <option value="date">Sort by Date</option>
                <option value="name">Sort by Name</option>
                <option value="amount">Sort by Amount</option>
              </select>
            </div>
          </div>
        )}

        {/* Content */}
        {cancellations.length === 0 ? (
          <EmptyState />
        ) : filteredCancellations.length === 0 ? (
          <NoResultsState />
        ) : viewMode === 'table' ? (
          <TableView />
        ) : (
          <CardView />
        )}
      </div>
    </div>
  )
}